"""Repeat the model's form steps for the next position (no model call per position).

A bid form often asks for one position after another with the same controls. After the model has filled one
position with `steps`, every value it typed or chose is traced back to the field of that position's line in our bid
table (material, quantity, prices, lead time, product filters). If every value is explained, the same steps are run
for the next position the page shows, with that position's values. A value that fits several fields (e.g. two
amounts of 0,00) is used only while those fields agree for the next position; anything unexplained, an unknown next
position or any error hands the form back to the model. The review check before signing compares the result.
"""
import re
from decimal import Decimal

Slot = tuple[int, int | None]          # (step index, field index in a fill_fields step or None)

FORMAT_ORDER = ("raw", "int", "de", "de_plain", "dot2")
MONEY = ("unit_price", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total")


def _de(value: Decimal, grouped: bool = True) -> str:
    text = f"{value:,.2f}".replace(",", "_").replace(".", ",").replace("_", ".")
    return text if grouped else text.replace(".", "")


def render(fmt: str, value) -> str:
    if fmt == "int":
        return str(int(Decimal(str(value))))
    if fmt in ("de", "de_plain", "dot2"):
        number = Decimal(str(value))
        return _de(number) if fmt == "de" else _de(number, grouped=False) if fmt == "de_plain" else f"{number:.2f}"
    return str(value)


def representations(row: dict, filters: dict | None) -> dict[str, list[tuple[str, str]]]:
    """field -> [(format, text)] of one line of the bid table."""
    reps: dict[str, list[tuple[str, str]]] = {}
    if row.get("material_number"):
        reps["material_number"] = [("raw", str(row["material_number"]))]
    for key in ("quantity", "lead_time_weeks"):
        if row.get(key) is not None:
            reps[key] = [("int", render("int", row[key])), ("raw", render("int", row[key]))]
